		function zoom(action) {
			if (action == "plus") {
				if (zoomVal >= 200) {
					alert("더이상 확대할 수 없습니다.");
				} else {
					zoomVal += 10;
					document.body.style.zoom = zoomVal + "%";
				}
			} else {
				if (zoomVal <= 70) {
					alert("더이상 축소할 수 없습니다.");
				} else {
					zoomVal -= 10;
					document.body.style.zoom = zoomVal + "%";
				}
			}
		}

