        if(userAgent.includes("chrome")){
            this.browser = "크롬";
        }else if(userAgent.includes("edge")){
            this.browser = "엣지";
        }else if(userAgent.includes("safari")){
            this.browser = "사파리";
        }else{
            this.browser = "기타";
        }

        this.createVisitorStat();

        document.querySelectorAll(".shareBtn").forEach(function(e){
            e.onclick = function(){
                var currentURL = window.location.href;

