            // $item.find(".accordion-collapse").addClass("show");
        } else {
            //    여기서는 DOM에서 바로 제거(remove)하지만, 숨기기(hide)만 하고 싶으면 .hide()로 대체.
            $item.remove();
        }
    });
});

